#!/usr/bin/env python3
"""crispr/crispr_crispor_design — auto-generated run.py (archetype=crispr).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "crispr"
BRAIN = "crispr"
SKILL = "crispr_crispor_design"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'crispr_crispor_design', 'n_guides': 0, 'guides_csv': '', 'best_guide': {'seq': '', 'cfd_score': 0.0, 'mit_score': 0.0}, 'diagnostics': {'brain': 'crispr', 'archetype': 'crispr'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """CRISPOR design via /home/zkyd/data2/mzy/crisporWebsite/crispor.py。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    seq = payload.get("target_sequence") or payload.get("sequence")
    genome = payload.get("genome", "hg38")
    pam = payload.get("pam", "NGG")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="crispor_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "crispor.py", "genome": genome, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_guides": 0, "guides_csv": "",
                "best_guide": {"seq": "", "cfd_score": 0.0, "mit_score": 0.0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not seq:
        return {"ok": False, "error": "需要 target_sequence", "diagnostics": diagnostics}
    _os.makedirs(out_dir, exist_ok=True)
    fa = _os.path.join(out_dir, "input.fa")
    with open(fa, "w") as fh: fh.write(f">target\n{seq}\n")
    out_tsv = _os.path.join(out_dir, "guides.tsv")
    cmd = ["python3", "/home/zkyd/data2/mzy/crisporWebsite/crispor.py",
           genome, fa, out_tsv, "--pam", pam]
    t0 = _time.time()
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 1800)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "crispor 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    guides = []
    if _os.path.isfile(out_tsv):
        with open(out_tsv) as fh:
            header = fh.readline().strip().split("\t")
            for ln in fh:
                fields = ln.strip().split("\t")
                if len(fields) == len(header):
                    guides.append(dict(zip(header, fields)))
    best = guides[0] if guides else None
    return {"ok": True, "skill_id": SKILL, "n_guides": len(guides),
            "guides_csv": out_tsv,
            "best_guide": {"seq": best.get("targetSeq", "") if best else "",
                          "cfd_score": float(best.get("cfdSpecScore", 0)) if best else 0.0,
                          "mit_score": float(best.get("mitSpecScore", 0)) if best else 0.0},
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "n_guides": len(guides)}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
